import {validateCosts} from './calc.mjs';
export const infraChecked='2026-10-01';
export const infraSources=[['Embedding price','https://developers.openai.com/api/docs/models/text-embedding-3-small'],['Railway resource rates','https://docs.railway.com/pricing'],['Minimum bill and network charges','https://docs.railway.com/pricing/understanding-your-bill'],['Average compute consumption','https://docs.railway.com/guides/right-size-cpu-memory'],['Unmanaged PostgreSQL / pgvector','https://docs.railway.com/databases/postgresql']];
export const infraFields=[['attempts','Example search attempts / month (including retries)',1000000000],['chunks','Searchable document passages',1000000000],['tokensPerChunk','Text per searchable passage (tokens, including overlap)',1000000],['queryTokens','Text per search question (tokens)',1000000],['dbRam','Average DB RAM (GB)',100000],['dbCpu','Average DB vCPU',100000],['appRam','Average app RAM (GB)',100000],['appCpu','Average app vCPU',100000],['storageGb','Average billable DB disk (GB)',1000000000],['egressKb','Information sent out per attempt (KB)',1000000000],['labourHours','Hours for support and upkeep / month',100000],['labourRate','Your hourly upkeep budget (USD)',1000000],['embeddingRate','Make text searchable (USD / 1M tokens)',1000000],['ramRate','RAM (USD / GB-month)',1000000],['cpuRate','CPU (USD / vCPU-month)',1000000],['diskRate','Disk (USD / GB-month)',1000000],['egressRate','Egress (USD / GB)',1000000],['minimum','Railway Pro monthly minimum (USD)',1000000]];
const common={tokensPerChunk:500,queryTokens:100,egressKb:100,labourRate:75,embeddingRate:.02,ramRate:10,cpuRate:20,diskRate:.15,egressRate:.05,minimum:20};
export const infraScenarios=[{id:'small-pilot',name:'Small pilot',assumptions:{...common,attempts:1000,chunks:10000,dbRam:2,dbCpu:.1,appRam:.5,appCpu:.05,storageGb:5,labourHours:2}},{id:'growing-corpus',name:'Growing document collection',assumptions:{...common,attempts:10000,chunks:100000,dbRam:4,dbCpu:.5,appRam:1,appCpu:.2,storageGb:20,labourHours:5}},{id:'larger-workload',name:'Larger workload',assumptions:{...common,attempts:100000,chunks:1000000,dbRam:16,dbCpu:2,appRam:2,appCpu:.5,storageGb:100,labourHours:12}}];
// Teaching equivalents only: do not use this heuristic as a tokenizer or measured file size.
export function documentEquivalents(a){const embeddedTokens=a.chunks*a.tokensPerChunk;const tokensPerWord=4/3,overlapMultiplier=1.25,wordsPerPage=500,pagesPerPdf=10,wordsPerArticle=1000;const sourceWords=embeddedTokens/overlapMultiplier/tokensPerWord;return {embedded_tokens:embeddedTokens,approx_pdfs:sourceWords/(wordsPerPage*pagesPerPdf),approx_articles:sourceWords/wordsPerArticle,assumptions:{tokens_per_word:tokensPerWord,overlap_multiplier:overlapMultiplier,words_per_page:wordsPerPage,pages_per_pdf:pagesPerPdf,words_per_article:wordsPerArticle},confidence:'Illustrative English-text equivalents, not measured files or a universal conversion. PDF and article counts are alternatives, not additive.'};}
export function infrastructureScenario(id,overrides={}){const preset=infraScenarios.find(p=>p.id===id);if(!preset)throw Error('Unknown infrastructure scenario');if(!overrides||typeof overrides!=='object'||Array.isArray(overrides))throw Error('Invalid scenario overrides');for(const [k,v]of Object.entries(overrides)){const field=infraFields.find(f=>f[0]===k);if(!field||typeof v!=='number'||!Number.isFinite(v)||v<0||v>field[2])throw Error('Invalid scenario sizing or price');}const a={...preset.assumptions,...overrides};const setupEmbeddings=a.chunks*a.tokensPerChunk*a.embeddingRate/1e6,queryEmbeddings=a.queryTokens*a.embeddingRate/1e6,dataTransfer=a.egressKb/1e6*a.egressRate,compute=(a.dbRam+a.appRam)*a.ramRate+(a.dbCpu+a.appCpu)*a.cpuRate,vectorStorage=a.storageGb*a.diskRate,maintenance=a.labourHours*a.labourRate;
// Defaults clear the Pro minimum on fixed resources alone. Lower custom sizes
// cannot map a varying minimum exactly into a fixed-plus-per-attempt model.
const minimumMappingExact=compute+vectorStorage>=a.minimum;
const additional_costs={setupEmbeddings,queryEmbeddings,retrieval:0,reranking:0,dataTransfer,otherUsage:0,vectorStorage,compute,monitoring:0,maintenance,amortizationMonths:12,allocatedSharePercent:100};
const derivedErrors=validateCosts(additional_costs);const canLoad=minimumMappingExact&&derivedErrors.length===0;
const resourceUsage=compute+vectorStorage+dataTransfer*a.attempts;const railwayMonthly=Math.max(a.minimum,resourceUsage);const knownReferenceMonthly=railwayMonthly+queryEmbeddings*a.attempts+setupEmbeddings/12+maintenance;
return {id,name:preset.name,document_equivalents:documentEquivalents(a),price_checked_utc:infraChecked,assumptions:a,sources:infraSources.map(([title,url])=>({title,url})),additional_costs,unknown_cost_fields:['setupParsing','setupIndexing'],minimum_mapping_exact:minimumMappingExact,can_load:canLoad,derived_cost_errors:derivedErrors,reference:{complete_attempts:a.attempts,railway_resource_usage_usd:resourceUsage,railway_billed_usd:railwayMonthly,known_monthly_including_amortized_embeddings_and_labour_usd:knownReferenceMonthly,excludes_generation_tokens:true},formulas:{setup_embeddings:'chunks × tokensPerChunk × embeddingRate ÷ 1,000,000',query_embeddings:'queryTokens × embeddingRate ÷ 1,000,000 per complete attempt',compute:'(dbRam + appRam) × ramRate + (dbCpu + appCpu) × cpuRate',storage:'storageGb × diskRate',transfer:'egressKb ÷ 1,000,000 × egressRate per complete attempt (decimal units)',railway_bill:'max(monthly minimum, compute + storage + public transfer); minimum is not an extra fee',maintenance:'illustrative labourHours × your labourRate; not a vendor price'},limitations:['Illustrative sizing, not a measured capacity or reliability recommendation','Average resource consumption, not provisioned machine size; disk is average billable usage','Unmanaged PostgreSQL with pgvector; backups, replicas, HA and external object storage not budgeted','Static corpus: no new or changed chunks/month; ongoing corpus re-embedding not included','Parsing/OCR and initial indexing/integration costs unknown; estimate remains partial','Retrieval uses the entered DB compute budget; no separate retrieval invoice assumed','No reranker or other metered service assumed; monitoring is built-in resource metrics only','Maintenance hours and hourly rate are hypothetical editable human budgets, not market benchmarks','Reference volume counts complete attempts, including repeats; calculator keeps current task volume and applies its own retries','No batch/free-tier/trial discount; tax and regional pricing excluded'],load_note:derivedErrors.length?'Cannot load: a derived cost exceeds the calculator limits. Reduce sizing or rates.':minimumMappingExact?'Can load cost assumptions. Keep task volume and retry settings; the calculator recomputes usage.':'Cannot load exact costs: edited fixed Railway resources fall below the plan minimum. Reference applies max() correctly, but generic calculator cannot model the varying minimum. Raise fixed usage or enter your own minimum-aware monthly bill.'};}
